const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two points
  const southJava = ee.Geometry.Point([110.2273416, -8.879787]);
  const northJavaSea = ee.Geometry.Point([109.953683, -5.741852]);

  // Get MODIS Ocean Color data for the specific date
  const date = '2019-08-04';
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select('chlor_a');

  const collectionSize = collection.size().getInfo();
  console.log(`Images found for ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the image for that day
  const image = collection.first();

  // Extract chlorophyll values at both points
  const southValue = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southJava,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a');

  const northValue = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northJavaSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a');

  const southChlor = southValue.getInfo();
  const northChlor = northValue.getInfo();

  console.log(`South Java chlorophyll: ${southChlor ? southChlor.toFixed(4) : 'No data'}`);
  console.log(`North Java Sea chlorophyll: ${northChlor ? northChlor.toFixed(4) : 'No data'}`);

  // Check for valid data
  if (southChlor === null || northChlor === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (isNaN(southChlor) || isNaN(northChlor) || southChlor === undefined || northChlor === undefined) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values and provide answer
  if (southChlor > northChlor) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
